<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import QRCode from 'qrcode'
import ManagementLayout from '@/components/ManagementLayout.vue'
import PageShell from '@/components/PageShell.vue'
import PageHeader from '@/components/PageHeader.vue'
import LoadingState from '@/components/LoadingState.vue'
import ErrorState from '@/components/ErrorState.vue'
import DeviceStatusBadge from '@/components/DeviceStatusBadge.vue'
import ConfirmDialog from '@/components/ConfirmDialog.vue'
import { platformApi, type Device } from '@/api/platform'
import { apiErrorMessage } from '@/api/http'
import { useUserStore } from '@/stores/user'

const route = useRoute(); const user = useUserStore()
const device = ref<Device | null>(null); const qrDataUrl = ref(''); const loading = ref(true); const saving = ref(false); const error = ref(''); const confirmUnbind = ref(false); const confirmStatus = ref(false)
async function load() { loading.value = true; error.value = ''; try { const id = Number(route.params.deviceId); device.value = (await platformApi.deviceDetail(id)).data; qrDataUrl.value = await QRCode.toDataURL(new URL(`/classroom/screen/${id}`, window.location.origin).toString(), { width: 260, margin: 2 }) } catch (cause) { error.value = apiErrorMessage(cause, '设备详情加载失败。') } finally { loading.value = false } }
async function unbind() { if (!device.value?.binding) return; saving.value = true; try { await platformApi.unbindDevice(device.value.binding.id); confirmUnbind.value = false; await load() } catch (cause) { error.value = apiErrorMessage(cause, '解除绑定失败。') } finally { saving.value = false } }
async function changeStatus() { if (!device.value) return; saving.value = true; try { await platformApi.updateDevice(device.value.id, { status: device.value.status === 'disabled' ? 'offline' : 'disabled' }); confirmStatus.value = false; await load() } catch (cause) { error.value = apiErrorMessage(cause, '设备状态更新失败。') } finally { saving.value = false } }
function formatTime(value: string | null) { return value ? new Date(value).toLocaleString() : '尚未上报' }
onMounted(load)
</script>
<template><ManagementLayout><PageShell variant="detail"><template #header><PageHeader :title="device?.name || '设备详情'" subtitle="设备码、绑定关系和后端心跳状态" eyebrow="设备详情" :back-to="{ name: 'devices' }" back-label="返回设备列表"><template #actions><button class="button secondary" @click="load">刷新状态</button><button v-if="user.isAdmin && device" class="button" :class="{ danger: device.status !== 'disabled' }" @click="confirmStatus = true">{{ device.status === 'disabled' ? '启用设备' : '停用设备' }}</button></template></PageHeader></template><LoadingState v-if="loading" /><ErrorState v-else-if="error" :description="error" @retry="load" /><template v-else-if="device"><section class="detail-grid"><article class="panel facts"><h2>设备状态</h2><dl><div><dt>设备码</dt><dd><code>{{ device.deviceCode }}</code></dd></div><div><dt>连接状态</dt><dd><DeviceStatusBadge :status="device.status" /></dd></div><div><dt>绑定状态</dt><dd><DeviceStatusBadge :status="device.status" :bound="Boolean(device.binding)" /></dd></div><div><dt>最近心跳</dt><dd>{{ formatTime(device.lastOnlineAt) }}</dd></div><div v-if="device.binding"><dt>教室 / 班级</dt><dd><RouterLink :to="{ name: 'classroom-detail', params: { classroomId: device.binding.classroomId } }">{{ device.binding.classroomName }}</RouterLink> · {{ device.binding.className }}</dd></div></dl><button v-if="user.isAdmin && device.binding" class="link danger-text" @click="confirmUnbind = true">解除当前绑定</button></article><article class="panel qr"><h2>大屏入口</h2><img v-if="qrDataUrl" :src="qrDataUrl" alt="大屏入口二维码" /><p>二维码只包含本机大屏页面地址，不包含教师 Token 或幼儿信息。课堂配对凭证仍由大屏页面按现有安全流程生成。</p><RouterLink class="button secondary" :to="{ name: 'classroom-screen', params: { deviceId: device.id } }" target="_blank">打开大屏页面</RouterLink></article></section></template></PageShell><ConfirmDialog v-model="confirmUnbind" title="解除设备绑定" message="解除后课堂准备页将不能再选择此设备。" confirm-label="确认解绑" danger :busy="saving" @confirm="unbind"/><ConfirmDialog v-model="confirmStatus" :title="device?.status === 'disabled' ? '启用设备' : '停用设备'" :message="device?.status === 'disabled' ? '设备启用后，需要重新发送心跳才会显示在线。' : '停用后设备不能参与新课堂。'" confirm-label="确认" :danger="device?.status !== 'disabled'" :busy="saving" @confirm="changeStatus"/></ManagementLayout></template>
<style scoped>.button{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:0 16px;border:0;border-radius:12px;background:#e99168;color:#fff;font:inherit;font-weight:700;text-decoration:none;cursor:pointer}.button.secondary{border:1px solid #edd5c5;background:#fff;color:#a9644b}.button.danger{background:#d85d57}.detail-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(260px,.7fr);gap:20px}.panel{margin-top:20px;padding:22px;border:1px solid #f0ddce;border-radius:18px;background:#fffdf9}.panel h2{margin:0 0 16px;color:#60483e}.facts dl{display:grid;gap:12px}.facts dl div{display:grid;grid-template-columns:120px 1fr;gap:15px;padding-bottom:12px;border-bottom:1px solid #f2e4d9}.facts dt{color:#9a7e6e}.facts dd{margin:0;color:#60483e}.facts a{color:#b76147}.qr{text-align:center}.qr img{width:min(260px,100%);border-radius:14px}.qr p{color:#8d7466;line-height:1.7;text-align:left}.link{border:0;background:none;color:#bd674b;cursor:pointer}.danger-text{color:#c44949}@media(max-width:760px){.detail-grid{grid-template-columns:1fr}}</style>
